const waitForPOS = setInterval(() => {
    if (frappe.pos && frappe.pos.item_selector) {
        clearInterval(waitForPOS);

        // Guardar referencia a la función original
        const original = frappe.pos.item_selector.update_item_details;

        frappe.pos.item_selector.update_item_details = function (item) {
            // Ejecutar la función original
            original.apply(this, arguments);

            const warehouse = frappe.pos.pos_profile_data.warehouse;

            // Verificar si el item usa lotes
            if (item.has_batch_no) {
                frappe.call({
                    method: "apps.sap_integration.sap_integration.api.obtener_lotes_disponibles.obtener_lotes_disponibles",
                    args: {
                        itemcode: item.item_code,
                        whscode: warehouse
                    },
                    callback: function (r) {
                        if (r.message && r.message.length > 0) {
                            const lotes = r.message.map(l => `${l.batchnum} (${l.quantity})`).join(", ");
                            frappe.show_alert({
                                message: `🧪 Lotes disponibles en <b>${warehouse}</b>: ${lotes}`,
                                indicator: "green"
                            });
                        } else {
                            frappe.show_alert({
                                message: `⚠️ No hay lotes disponibles en <b>${warehouse}</b>`,
                                indicator: "red"
                            });
                        }
                    }
                });
            } else {
                // Si no usa lotes, verificar stock total
                frappe.call({
                    method: "apps.sap_integration.sap_integration.api.obtener_lotes_disponibles.validar_stock_disponible",
                    args: {
                        itemcode: item.item_code,
                        whscode: warehouse,
                        cantidad_solicitada: item.qty
                    },
                    callback: function (r) {
                        if (r.message) {
                            frappe.show_alert({
                                message: `📦 Stock SAP en <b>${warehouse}</b>: ${r.message.stock}`,
                                indicator: r.message.stock > 0 ? "green" : "red"
                            });

                            if (!r.message.disponible) {
                                frappe.msgprint("❌ " + r.message.mensaje);
                            }
                        }
                    }
                });
            }
        };
    }
}, 300);
